 @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Bill Preview'),backgroundColor:const Color(0xFFFFC107)),body:Column(children:[Expanded(child:SingleChildScrollView(padding:const EdgeInsets.all(16),child:Screenshot(controller:shot,child:receipt()))),Padding(padding:const EdgeInsets.fromLTRB(16,8,16,20),child:Row(children:[Expanded(child:FilledButton.icon(onPressed:saving?null:saveGallery,icon:const Icon(Icons.save_alt),label:Text(saving?'SAVING...':'SAVE TO GALLERY'))),const SizedBox(width:10),IconButton.filled(onPressed:share,icon:const Icon(Icons.share))]))]));}

class Bills extends StatelessWidget{const Bills({super.key});@override Widget build(BuildContext c)=>AnimatedBuilder(animation:store,builder:(c,_){if(store.bills.isEmpty)return const Center(child:Text('No bills yet'));final sales=store.bills.fold<double>(0,(s,b)=>s+b.total);return Column(children:[Card(margin:const EdgeInsets.all(12),child:Padding(padding:const EdgeInsets.all(16),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('TOTAL SALES'),Text('₹${sales.toStringAsFixed(2)}',style:const TextStyle(fontSize:26,fontWeight:FontWeight.w900))]),Text('${store.bills.length} bills')])),Expanded(child:ListView.builder(itemCount:store.bills.length,itemBuilder:(c,i){final b=store.bills[i];return ListTile(leading:CircleAvatar(backgroundColor:const Color(0xFFFFC107),child:Text('${i+1}')),title:Text('Bill #${b.id.substring(b.id.length-6)}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${b.payment} • ${b.items.length} items'),trailing:Text('₹${b.total.toStringAsFixed(0)}',style:const TextStyle(fontWeight:FontWeight.w900)),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>BillPreview(bill:b))));}))]);});}

class Products extends StatelessWidget{const Products({super.key});@override Widget build(BuildContext c)=>AnimatedBuilder(animation:store,builder:(c,_){return ListView(padding:const EdgeInsets.all(12),children:[FilledButton.icon(onPressed:()=>edit(c),icon:const Icon(Icons.add),label:const Text('ADD NEW ITEM')),const SizedBox(height:8),...store.products.map((p)=>Card(child:ListTile(title:Text(p.name,style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${p.category} • ₹${p.price.toStringAsFixed(0)}'),leading:Switch(value:p.active,onChanged:(v)async{p.active=v;await store.saveProducts();}),trailing:IconButton(icon:const Icon(Icons.edit),onPressed:()=>edit(c,p))))]);});}
 static Future<void> edit(BuildContext c,[Product? p])async{final n=TextEditingController(text:p?.name??''),cat=TextEditingController(text:p?.category??'Fast Food'),pr=TextEditingController(text:p?.price.toString()??'');await showDialog(context:c,builder:(d)=>AlertDialog(title:Text(p==null?'Add Item':'Edit Item'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Item name')),TextField(controller:cat,decoration:const InputDecoration(labelText:'Category')),TextField(controller:pr,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Price'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('CANCEL')),FilledButton(onPressed:()async{final price=double.tryParse(pr.text);if(n.text.trim().isEmpty||price==null)return;if(p==null)store.products.add(Product(id:DateTime.now().millisecondsSinceEpoch.toString(),name:n.text.trim(),category:cat.text.trim(),price:price));else{p.name=n.text.trim();p.category=cat.text.trim();p.price=price;}await store.saveProducts();if(d.mounted)Navigator.pop(d);},child:const Text('SAVE'))]));}
}
